var createCounter = function(init) {
    let currentCount = init;
    return{
    increment:()=>{
        return ++currentCount;
    },
    reset:()=>{
        currentCount=init;
        return currentCount;
    },
    decrement:()=>{
        return --currentCount;
    }
    }
};

